const express = require('express');
const { Pool } = require('pg');
const { requireAuth } = require('./auth');

const app = express();
const pool = new Pool({ connectionString: process.env.DB_SESSIONS });

app.get('/api/sessions/:sid/status', requireAuth, async (req, res) => {
  const { sid } = req.params;

  const query = 'SELECT sess, expire FROM "session" WHERE sid = $1';
  const { rows } = await pool.query(query, [sid]);

  if (rows.length === 0) {
    return res.status(404).json({ active: false });
  }

  // Ensure caller owns the session being probed
  const sessionUser = rows[0].sess?.user;
  if (sessionUser?.id !== req.user.id && !req.user.isAdmin) {
    return res.status(403).json({ error: 'Access denied: cannot query session status of another user' });
  }

  const isExpired = new Date(rows[0].expire) < new Date();
  res.json({ sid, active: !isExpired, expiresAt: rows[0].expire });
});

app.listen(8100);
